SELECT
  100.0 * SUM(CASE WHEN SEX = 'M' AND Admission = '+' THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN SEX = 'M' AND Admission = '-' THEN 1 ELSE 0 END), 0) AS percentage_deviation
FROM Patient;

SELECT 100.0 * SUM(CASE WHEN Diagnosis LIKE '%ITP%' THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN Diagnosis LIKE '%SLE%' THEN 1 ELSE 0 END), 0) AS proportion
FROM Examination
WHERE Symptoms LIKE '%thrombocytopenia%';
